// The tenant and the key PREFIXES only. The raw keys stay in the Register Free Key output (shown once).
const reg = $('Register Free Key').first().json;
const me = $json || {};
const t = me.tenant || {};
return [{ json: {
  ok: me.ok === true,
  tenant_id: t.id || null,
  tenant_via: t.via || null,
  wallet_label: t.wallet_label || null,
  key_prefix: reg.key_prefix || null,
  keys: (me.keys || []).map((k) => ({ prefix: k.prefix, env: k.env, revoked: Boolean(k.revoked) })),
  next_step: me.next_step ? (me.next_step.title || me.next_step.id) : null,
  save_it: 'Copy api_key from the Register Free Key output into Credentials → Taifoon Relayer API now. It is not shown again.',
} }];
